diff --git a/internal/checkpoint/file.go b/internal/checkpoint/file.go
new file mode 100644
--- /dev/null
+++ b/internal/checkpoint/file.go
@@ -0,0 +1,65 @@
+package checkpoint
+
+import (
+	"errors"
+	"fmt"
+	"io/fs"
+	"log/slog"
+	"os"
+	"path/filepath"
+	"strconv"
+	"strings"
+)
+
+// File stores the last processed stream offset in a single small file.
+type File struct {
+	path  string
+	fresh int64
+	log   *slog.Logger
+}
+
+func NewFile(path string, fresh int64, log *slog.Logger) *File {
+	return &File{path: path, fresh: fresh, log: log}
+}
+
+// Load returns the offset to resume from. A missing file means a fresh consumer,
+// which starts at the offset given to NewFile.
+func (f *File) Load() (int64, error) {
+	b, err := os.ReadFile(f.path)
+	if errors.Is(err, fs.ErrNotExist) {
+		return f.fresh, nil
+	}
+	if err != nil {
+		return 0, fmt.Errorf("read checkpoint %s: %w", f.path, err)
+	}
+	off, err := strconv.ParseInt(strings.TrimSpace(string(b)), 10, 64)
+	if err != nil {
+		f.log.Warn("checkpoint content not an offset, starting fresh", "path", f.path, "err", err)
+		return f.fresh, nil
+	}
+	return off, nil
+}
+
+// Save writes the offset atomically: a temp file in the same directory, then rename.
+func (f *File) Save(off int64) error {
+	tmp, err := os.CreateTemp(filepath.Dir(f.path), ".checkpoint-*")
+	if err != nil {
+		return fmt.Errorf("create temp checkpoint: %w", err)
+	}
+	defer os.Remove(tmp.Name())
+	if _, err := tmp.WriteString(strconv.FormatInt(off, 10)); err != nil {
+		tmp.Close()
+		return fmt.Errorf("write temp checkpoint: %w", err)
+	}
+	if err := tmp.Sync(); err != nil {
+		tmp.Close()
+		return fmt.Errorf("sync temp checkpoint: %w", err)
+	}
+	if err := tmp.Close(); err != nil {
+		return fmt.Errorf("close temp checkpoint: %w", err)
+	}
+	if err := os.Rename(tmp.Name(), f.path); err != nil {
+		return fmt.Errorf("rename checkpoint: %w", err)
+	}
+	return nil
+}
