@@ -0,0 +1,43 @@
+import type { Pool } from "pg";
+
+export type Entry = {
+  player_id: string;
+  display_name: string;
+  score: number;
+};
+
+const TTL_MS = 30_000;
+
+/**
+ * Holds the current top 500, highest score first, and reloads it at most every
+ * 30 seconds. Concurrent callers during a reload share the same query.
+ */
+export class LeaderboardCache {
+  private entries: Entry[] = [];
+  private loadedAt = 0;
+  private pending: Promise<Entry[]> | null = null;
+
+  constructor(private readonly pool: Pool) {}
+
+  async top(): Promise<Entry[]> {
+    if (Date.now() - this.loadedAt < TTL_MS) {
+      return this.entries;
+    }
+    if (!this.pending) {
+      this.pending = this.load().finally(() => {
+        this.pending = null;
+      });
+    }
+    this.entries = await this.pending;
+    this.loadedAt = Date.now();
+    return this.entries;
+  }
+
+  private async load(): Promise<Entry[]> {
+    const { rows } = await this.pool.query<Entry>(
+      'SELECT player_id, display_name, score ' +
+        "FROM leaderboard ORDER BY score DESC, player_id LIMIT 500",
+    );
+    return rows;
+  }
+}
