+import type { Pool } from "pg";
+import { LeaderboardCache, type Entry } from "./cache";
+
+function fakePool(batches: Entry[][]): { pool: Pool; calls: () => number } {
+  let calls = 0;
+  const pool = {
+    query: jest.fn(async () => {
+      const rows = batches[Math.min(calls, batches.length - 1)];
+      calls++;
+      return { rows };
+    }),
+  } as unknown as Pool;
+  return { pool, calls: () => calls };
+}
+
+const alice: Entry = { player_id: "p1", display_name: "Alice", score: 900 };
+const bob: Entry = { player_id: "p2", display_name: "Bob", score: 700 };
+
+describe("LeaderboardCache", () => {
+  afterEach(() => jest.useRealTimers());
+
+  it("serves the cached list inside the TTL", () => {
+    const { pool, calls } = fakePool([[alice, bob], [bob]]);
+    const cache = new LeaderboardCache(pool);
+    cache.top().then(() => {
+      cache.top().then((second) => {
+        expect(second).toEqual([alice, bob]);
+        expect(calls()).toBe(1);
+      });
+    });
+  });
+
+  it("reloads after the TTL", () => {
+    jest.useFakeTimers({ now: 1_000_000 });
+    const { pool, calls } = fakePool([[alice, bob], [bob]]);
+    const cache = new LeaderboardCache(pool);
+    cache.top().then(() => {
+      jest.setSystemTime(1_000_000 + 31_000);
+      cache.top().then((second) => {
+        expect(second).toEqual([bob]);
+        expect(calls()).toBe(2);
+      });
+    });
+  });
+});
