+        let second = first + 1 + bytes[first + 1..].iter().position(|&b| b == b'|')?;
+        let ts = std::str::from_utf8(&bytes[..first]).ok()?;
+        let level = std::str::from_utf8(&bytes[first + 1..second]).ok()?;
+        let message = String::from_utf8_lossy(&bytes[second + 1..]).into_owned();
+        Some(Record {
+            ts_millis: ts.parse().ok()?,
+            level: level.parse().ok()?,
+            message,
+        })
     }
