+package com.acme.orders.imports;
+
+import java.util.ArrayList;
+import java.util.List;
+
+import org.slf4j.Logger;
+import org.slf4j.LoggerFactory;
+import org.springframework.dao.DataIntegrityViolationException;
+import org.springframework.stereotype.Service;
+import org.springframework.transaction.annotation.Transactional;
+
+import com.acme.orders.domain.Order;
+import com.acme.orders.domain.OrderLine;
+import com.acme.orders.repo.OrderLineRepository;
+import com.acme.orders.repo.OrderRepository;
+
+/**
+ * Imports orders from a partner file. Each order is all-or-nothing: an order whose
+ * header or any line violates a constraint is rejected as a whole and reported,
+ * and the rest of the file carries on.
+ */
+@Service
+public class OrderImportService {
+
+    private static final Logger log = LoggerFactory.getLogger(OrderImportService.class);
+
+    private final OrderRepository orders;
+    private final OrderLineRepository lines;
+
+    public OrderImportService(OrderRepository orders, OrderLineRepository lines) {
+        this.orders = orders;
+        this.lines = lines;
+    }
+
+    public ImportResult importAll(List<OrderRow> rows) {
+        int imported = 0;
+        List<RejectedRow> rejected = new ArrayList<>();
+        for (OrderRow row : rows) {
+            try {
+                importOne(row);
+                imported++;
+            } catch (DataIntegrityViolationException e) {
+                log.warn("order {} rejected: {}", row.externalId(), e.getMostSpecificCause().getMessage());
+                rejected.add(new RejectedRow(row.externalId(), e.getMostSpecificCause().getMessage()));
+            }
+        }
+        return new ImportResult(imported, List.copyOf(rejected));
+    }
+
+    @Transactional
+    public void importOne(OrderRow row) {
+        Order order = orders.save(Order.fromImport(row.externalId(), row.customerId(), row.placedAt()));
+        for (OrderRow.Line line : row.lines()) {
+            lines.save(OrderLine.of(order, line.sku(), line.quantity(), line.unitPriceCents()));
+        }
+    }
+}
