@@ -0,0 +1,42 @@
+use std::collections::BTreeMap;
+
+use crate::account::{Account, AccountId};
+use crate::error::LedgerError;
+
+#[derive(Debug, Clone, PartialEq, Eq)]
+pub struct Transfer {
+    pub from: AccountId,
+    pub to: AccountId,
+    pub amount_cents: i64,
+}
+
+/// Moves money between two accounts in the book. The source is debited under the
+/// same rules as a direct debit from it; either both balances change or neither does.
+pub fn transfer(book: &mut BTreeMap<AccountId, Account>, t: &Transfer) -> Result<(), LedgerError> {
+    if t.amount_cents <= 0 {
+        return Err(LedgerError::InvalidAmount(t.amount_cents));
+    }
+    if t.from == t.to {
+        return Err(LedgerError::SameAccount);
+    }
+    let dst = book.get(&t.to).ok_or(LedgerError::NotFound(t.to))?;
+    if dst.balance_cents.checked_add(t.amount_cents).is_none() {
+        return Err(LedgerError::Overflow);
+    }
+
+    let src = book.get_mut(&t.from).ok_or(LedgerError::NotFound(t.from))?;
+    if src.frozen {
+        return Err(LedgerError::Frozen(src.id));
+    }
+    if src.balance_cents < t.amount_cents {
+        return Err(LedgerError::InsufficientFunds {
+            account: src.id,
+            short_by: t.amount_cents - src.balance_cents,
+        });
+    }
+    src.balance_cents -= t.amount_cents;
+
+    let dst = book.get_mut(&t.to).expect("checked above");
+    dst.balance_cents += t.amount_cents;
+    Ok(())
+}
