+package com.acme.mail.suppression;
+
+import java.io.IOException;
+import java.net.URI;
+import java.net.URLEncoder;
+import java.net.http.HttpClient;
+import java.net.http.HttpRequest;
+import java.net.http.HttpResponse;
+import java.nio.charset.StandardCharsets;
+import java.time.Duration;
+
+import org.slf4j.Logger;
+import org.slf4j.LoggerFactory;
+
+/** Asks the suppression service whether an address has unsubscribed or bounced. */
+public class SuppressionClient {
+
+    private static final Logger log = LoggerFactory.getLogger(SuppressionClient.class);
+
+    private final HttpClient http;
+    private final URI baseUri;
+
+    public SuppressionClient(HttpClient http, URI baseUri) {
+        this.http = http;
+        this.baseUri = baseUri;
+    }
+
+    public boolean isSuppressed(String email) {
+        URI uri = baseUri.resolve("/v1/suppressions/" + URLEncoder.encode(email, StandardCharsets.UTF_8));
+        HttpRequest request = HttpRequest.newBuilder(uri)
+                .timeout(Duration.ofSeconds(2))
+                .GET()
+                .build();
+        try {
+            HttpResponse<Void> response = http.send(request, HttpResponse.BodyHandlers.discarding());
+            return switch (response.statusCode()) {
+                case 200 -> true;
+                case 404 -> false;
+                default -> {
+                    log.warn("suppression service returned {} for a lookup", response.statusCode());
+                    throw new SuppressionUnavailableException(
+                            "suppression service returned " + response.statusCode(), null);
+                }
+            };
+        } catch (IOException e) {
+            throw new SuppressionUnavailableException("suppression lookup failed", e);
+        } catch (InterruptedException e) {
+            Thread.currentThread().interrupt();
+            throw new SuppressionUnavailableException("interrupted during suppression lookup", e);
+        }
+    }
+}
